from pathlib import Path
import json,subprocess,sys,hashlib
R=Path(__file__).resolve().parent
for script in ['validate_model.py','check_all_layers.py','check_layer_components.py','check_thin_features.py','check_feature_losses.py','check_architectural_rays.py']:
 subprocess.run([sys.executable,str(R/script)],check=True)
v=json.loads((R/'validation.json').read_text());l=json.loads((R/'layer-opening-check.json').read_text());lc=json.loads((R/'layer-component-check.json').read_text());f=json.loads((R/'feature-loss-locations.json').read_text());a=json.loads((R/'architectural-ray-check.json').read_text())
checks={**v['checks'],**lc['checks'],**a['checks'],'all_validators_exit_zero':True,'all_original_sections_valid_without_repair':True,'canonical_v3_hash_matches':hashlib.sha256((R/'check_thin_features.py').read_bytes()).hexdigest()=='059f7378c74a1400dcf010365ebf35df3027fd853f1c960462a233dc68ce8915'}
report={'passed':all(checks.values()),'checks':checks,'layer_pitch_mm':.2,'layer_offset_mm':.071,'layer_count':l['sampled_layers'],'original_polygon_count':len(lc['original_component_checks']),'opening_reference_width_mm':.8,'maximum_whole_layer_loss_fraction':l['maximum_opening_loss_fraction'],'maximum_original_component_loss_fraction':f['maximum_original_component_loss_fraction'],'accepted_specific_corner_exception':{'tower_cap_piers':12,'tower_cap_layer_samples':48,'western_gable_crest_layer_samples':4,'total_layer_samples':52,'bounds_corner_radius_mm':.41,'scope':'Only documented rectangular cap-pier and gable-crest corners; not a global threshold relaxation or exemption for thin skins. Parent accepted subject to independent reproduction.'},'stl_sha256':v['stl_sha256'],'warnings':['52 sampled corner losses comprise48 samples from12 tower-cap piers plus4 western gable-crest samples, not52 columns.','Not global wall thickness, slicing toolpaths or a physical print guarantee.','West RC extent and all building dimensions are bounded cross-year image/repair-drawing interpretation, not survey.']}
(R/'qa-summary.json').write_text(json.dumps(report,ensure_ascii=False,indent=2));assert report['passed']
